"      // 레이어 수직 높이 (Z축 방향 높이: 0층이 가장 아래, 3층이 가장 위)
      // Z값이 높을수록 위로 적층되며, 3D 수식에 따라 기울여 렌더링
      const h = effectiveLayer * LAYER_GAP;

      // 3D X축 회전 변환 공식 적용
      // Z축 높이 h를 더해 수직으로 층을 쌓아 올립니다.
      const rotatedY = worldY * Math.cos(tiltAngle) - h * Math.sin(tiltAngle);
      const depth = worldY * Math.sin(tiltAngle) + h * Math.cos(tiltAngle);

      const perspectiveScale = cameraDist / (cameraDist + depth);

      const targetRenderX = cx + worldX * zoom * perspectiveScale;
      const targetRenderY = cy + rotatedY * zoom * perspectiveScale;"
